            for v, w, idx in adj[u]:
                if idx not in excluded_edge_indices and v not in visited:
                    visited.add(v)
                    q.append(v)
        return False

    # Check if already disconnected (0 edges)
    if not is_connected(set()):
        return "0\n0\n"

    # Check 1 edge
    min_cost_one = float('inf')
    best_one = None

    for i in range(m):
        if is_connected({edges[i][3]}):
            cost = edges[i][2]
