                min_cost_one = cost
                best_one = [edges[i][3]]

    if best_one is not None:
        return f"{min_cost_one}\n1\n{' '.join(map(str, best_one))}\n"

    # Check 2 edges
    min_cost_two = float('inf')
    best_two = None

    for i in range(m):
        for j in range(i + 1, m):
            if is_connected({edges[i][3], edges[j][3]}):
                cost = edges[i][2] + edges[j][2]
                if cost < min_cost_two:
