def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse events
    events = []
    for i in range(1, n + 1):
        line = lines[i]
        if line.startswith('1'):
            events.append('1')
        else:
            events.append(line.split()[1])

    # Group friends by handle periods (between type 1 events)
    periods = []
    current = []
    for event in events:
        if event == '1':
            if current:
                periods.append(tuple(sorted(current)))
            current = []
        else:
            current.append(event)
    if current:
        periods.append(tuple(sorted(current)))

    # Collect all unique friends
    all_friends = set()
    for p in periods:
        all_friends.update(p)
    all_friends = sorted(all_friends)

    # Map friends to indices
    friend_to_idx = {f: i for i, f in enumerate(all_friends)}
    n_friends = len(all_friends)

    # Build conflict graph using bitmasks
    # conflict[i] contains bitmask of friends that conflict with friend i
    conflict = [0] * n_friends
    for period in periods:
        friends_in_period = [friend_to_idx[x] for x in period]
        if len(friends_in_period) < 2:
            continue
        for i in range(len(friends_in_period)):
            for j in range(i + 1, len(friends_in_period)):
                conflict[friends_in_period[i]] |= (1 << friends_in_period[j])

    # Maximum independent set with pruning
    max_friends = 0

    def solve(idx, mask, count):
        nonlocal max_friends

        # Pruning: if we can't beat current best, stop
        remaining = n_friends - idx
        if count + remaining <= max_friends:
            return

        # Update max
        if count > max_friends:
            max_friends = count

        if idx == n_friends:
            return

        # Try including friend idx (if no conflict)
        if not ((conflict[idx] & mask) > 0):
            count += 1
            solve(idx + 1, mask | (1 << idx), count)
            count -= 1

        # Try not including friend idx
        solve(idx + 1, mask, count)

    # Start recursion
    solve(0, 0, 0)

    return str(max_friends)

