def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return '\n-1\n'

    lines = input_str.split('\n')
    lines = [l.strip() for l in lines if l.strip()]
    idx = 0

    # Parse n1, n2, n3, n4
    if idx >= len(lines):
        return '\n-1\n'
    n1, n2, n3, n4 = map(int, lines[idx].split())
    idx += 1

    # Parse costs for each layer
    layer_costs = []
    for _ in range(4):
        if idx >= len(lines):
            return '\n-1\n'
        layer_costs.append(list(map(int, lines[idx].split())))
        idx += 1

    INF = float('inf')

    # Build incompatibility maps
    # bad_map[y] = set of x-1 such that item x from prev layer incompatible with item y from curr layer

    bad_1_2 = {}
    idx += 1
    if idx < len(lines):
        m1 = int(lines[idx])
        idx += 1
        for _ in range(m1):
            if idx >= len(lines):
                break
            x, y = map(int, lines[idx].split())
            idx += 1
            if y not in bad_1_2:
                bad_1_2[y] = set()
            bad_1_2[y].add(x - 1)

    bad_2_3 = {}
    idx += 1
    if idx < len(lines):
        m2 = int(lines[idx])
        idx += 1
        for _ in range(m2):
            if idx >= len(lines):
                break
            x, y = map(int, lines[idx].split())
            idx += 1
            if y not in bad_2_3:
                bad_2_3[y] = set()
            bad_2_3[y].add(x - 1)

    bad_3_4 = {}
    idx += 1
    if idx < len(lines):
        m3 = int(lines[idx])
        idx += 1
        for _ in range(m3):
            if idx >= len(lines):
                break
            x, y = map(int, lines[idx].split())
            idx += 1
            if y not in bad_3_4:
                bad_3_4[y] = set()
            bad_3_4[y].add(x - 1)

    # Helper function for layer transition
    def transition(prev_dp, prev_n, curr_costs, curr_n, bad_map):
        next_dp = [INF] * curr_n

        # Sort previous layer by dp values (ascending cost)
        sorted_prev = sorted([(prev_dp[i], i) for i in range(prev_n)])

        # Check global min to ensure at least one valid path exists
        if not sorted_prev:
            return next_dp

        for i in range(curr_n):
            cost_i = curr_costs[i]
            prev_idx = bad_map.get(i, set()) if bad_map else set()

            # Try items from previous layer in order of increasing cost
            found = False
            for prev_cost, prev_idx_val in sorted_prev:
                if prev_idx_val in prev_idx:
                    # Incompatible, continue to next
                    continue
                # Found a compatible item
                next_dp[i] = prev_cost + cost_i
                found = True
                break
            if not found:
                next_dp[i] = INF

        return next_dp

    # Start with layer 0 costs
    dp = layer_costs[0]

    # Transition 0 -> 1
    if dp:
        dp = transition(dp, n1, layer_costs[1], n2, bad_1_2)

    # Transition 1 -> 2
    if dp and n2 > 0 and layer_costs[2]:
        dp = transition(dp, n2, layer_costs[2], n3, bad_2_3)

    # Transition 2 -> 3
    if dp and n3 > 0 and layer_costs[3]:
        dp = transition(dp, n3, layer_costs[3], n4, bad_3_4)

    # Find minimum cost in final layer
    if dp:
        min_cost = min(dp)
        if min_cost == INF:
            return '\n-1\n'
        else:
            return f'\n{min_cost}\n'
    else:
        return '\n-1\n'

