def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (n + 1)
    on_stack = [False] * (n + 1)
    parent = {}
    cycles = []

    def dfs_cycle(u):
        visited[u] = True
        on_stack[u] = True
        parent[u] = -1

        for v in adj[u]:
            if v == -1:
                continue
            if not visited[v]:
                dfs_cycle(v)
            if on_stack[v]:
                if v != parent[u] and parent[u] != -1:
                    # Found back edge u-v creating a cycle
                    path = [v]
                    cur = u
                    while cur != v:
                        path.append(cur)
                        cur = parent[cur]
                    cycles.append(path)

        on_stack[u] = False

    def dfs_spanning(u):
        visited[u] = True
        parent[u] = -1
        on_stack[u] = True

        for v in adj[u]:
            if v == parent.get(u):
                continue
            if not visited[v]:
                parent[v] = u
                dfs_spanning(v)
            if on_stack[v]:
                # Back edge to ancestor - found a cycle
                cycle = [v]
                cur = u
                while cur != v:
                    cycle.append(cur)
                    cur = parent[cur]
                cycles.append(list(reversed(cycle)))

        on_stack[u] = False

    for i in range(1, n + 1):
        if not visited[i]:
            visited[i] = True
            dfs_spanning(i)

    # Filter valid cycles: length >= 3 and length % 3 != 0
