        d1 = cross_product(p3, p1, p4)
        d2 = cross_product(p3, p2, p4)
        d3 = cross_product(p1, p3, p2)
        d4 = cross_product(p1, p4, p2)
        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
