def solve(N, x, M, y):
    center_dist = abs(x - y)

    intersecting_pairs = 0
    for r1 in range(1, N+1):
        for r2 in range(1, M+1):
            diff = abs(r1 - r2)
            size_sum = r1 + r2
            if diff < center_dist < size_sum:
                intersecting_pairs += 2
            elif center_dist == diff or center_dist == size_sum:
                intersecting_pairs += 1

    return 1 + N + M + intersecting_pairs

