def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    g, x, y = extended_gcd(b % a, a)
    return g, y - (b // a) * x, x

def mod_inverse(a, m):
    g, x, _ = extended_gcd(a, m)
    if g != 1:
        return None
    return x % m

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def nCr_mod_prime(n, r, p):
    """Compute C(n, r) mod p where p is prime"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    numerator = 1
    denominator = 1

    for i in range(r):
        numerator = (numerator * (n - i)) % p
        denominator = (denominator * (i + 1)) % p

    return (numerator * pow(denominator, p - 2, p)) % p

def nCr_mod_prime_power(n, r, p, e):
    """Compute C(n, r) mod p^e where p is prime"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    # Count exponent of p in C(n, r)
    # Using Legendre's formula
    def legendre(n, p):
        count = 0
        i = p
        while i <= n:
            count += n // i
            i *= p
        return count

    v = legendre(n, p) - legendre(r, p) - legendre(n - r, p)

    if v >= e:
        return 0

    modulus = p ** e

    # Remove factors of p from numerator and denominator
    numerator = 1
    denominator = 1

    for i in range(r):
        numerator = numerator * (n - i)
        denominator = denominator * (i + 1)

    # Remove p^v from numerator
    while v > 0:
        numerator %= (p * modulus)  # Keep in range
        numerator //= p
        v -= 1

    # Divide out common factors from numerator and denominator
    for i in range(r):
        if n - i > 0:
            while numerator % p == 0 and denominator % p == 0:
                numerator //= p
                denominator //= p
                v += 0

    # Now use nCr with removed p factors
    # Compute modular inverse of denominator mod p^e
    inv = mod_inverse(denominator % modulus, modulus)

    if inv is None:
        # denominator shares factor with modulus, should not happen after proper division
        return 0

    result = (numerator % modulus * inv) % modulus
    return result

def factorize(n):
    """Return dict of prime power factors: {p: e}"""
    factors = {}
    i = 2
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            factors[i] = count
        i += 1
    if n > 1:
        factors[n] = 1
    return factors

def crt_combine(remainders, moduli):
    """Combine using Chinese Remainder Theorem"""
    result = 0
    m = 1
    for md in moduli:
        m *= md

    for r, mod in zip(remainders, moduli):
        mi = m // mod
        inv = mod_inverse(mi % mod, mod)
        result += r * mi * inv
        result %= m
    return result

def nCr_mod(n, r, p):
    """Compute C(n, r) mod p for any p"""
    if r < 0 or r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r > n // 2:
        r = n - r

    if p == 1:
        return 0

    factors = factorize(p)
    remainders = []
    moduli = []

    for prime, exp in factors.items():
        mod = prime ** exp
        remainder = nCr_mod_prime_power(n, r, prime, exp)
        remainders.append(remainder)
        moduli.append(mod)

    if len(remainders) == 0:
        return 0
    return crt_combine(remainders, moduli)

