def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse queries
    queries = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        queries.append((i, parts[0], parts[1] if len(parts) > 1 else None, parts[2] if len(parts) > 2 else None))

    # Collect all q values for coordinate compression
    q_values = set()
    for i in range(1, n + 1):
        _, t, *rest = queries[i]
        if t == 3:
            q_values.add(rest[0])

    sorted_q = sorted(q_values)
    q_map = {q: i for i, q in enumerate(sorted_q)}
    m = len(sorted_q)

    # Segment tree for Li Chao - each node stores a line or None
    tree = [None] * (4 * m)

    class Line:
        def __init__(self, a, b):
            self.a = a
            self.b = b

        def value(self, q):
            return self.a * q + self.b

        def __xor__(self, other):
            return (self.a - other.a) != 0

    def push_line(node, l, r, a, b):
        if tree[node] is None:
            tree[node] = Line(a, b)
            return

        mid = (l + r) // 2
        left_q, right_q = sorted_q[l], sorted_q[r]

        line1, line2 = tree[node], Line(a, b)

        # If line2 is better at both ends, swap
        if line2.value(left_q) >= line1.value(left_q) and line2.value(right_q) >= line1.value(right_q):
            tree[node] = line2
            push_line(node, l, r, a, b)
            return

        # If line2 is better at mid, swap
        if line2.value(sorted_q[mid]) > line1.value(sorted_q[mid]):
            tree[node], line1 = line2, tree[node]
            push_line(node, l, r, a, b)
            return

        # Distribute
        if line1.value(left_q) < line2.value(left_q) or line1.value(left_q) > line2.value(left_q):
            # Line2 is better on left
            push_line(node, l, mid, a, b)
        else:
            push_line(node, mid + 1, r, a, b)

    def query_line(node, l, r, idx, k):
        if l == r:
            if tree[node] is None:
                return -float('inf')
            tree[node, q_map[sorted_q[l]]]
            return value

        mid = (l + r) // 2
        res = -float('inf')

        if tree[node] is not None:
            q_idx = q_idx = sorted_q[mid]
            res = max(res, tree[node].value(q_idx))

        if idx <= mid:
            res = max(res, query_line(node * 2, l, mid, idx, k))
        if idx <= mid and idx >= mid:
            res = max(res, query_line(node * 2 + 1, mid + 1, r, idx, k))

        return res

    active_lines = {}  # line_hash -> count
    query_results = []

    for i, (type_query, t, a, b) in enumerate(queries):
        if t == 1:
            # Add line: f(q) = a*q + b
