    lines = input_str.strip().split('\n')
    n = int(lines[0])

    queries = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        queries.append((parts))

    q_values = set()
    for q in range(1, n + 1):
        t, *_ = queries[q]
        if t == 3:
            q_values.add(queries[q][2])

    sorted_q = sorted(q_values)
    m = len(sorted_q)

    tree = [None] * (4 * m + 1)

    def get_value(a, b, q):
        return a * q + b

    def update(node, ql, qr, a, b, v):
        if vl == qr:
            if tree[node] is None or get_value(tree[node][0], tree[node][1], sorted_q[l]) < v:
                tree[node] = (a, b)
            return

        mid = (ql + qr) // 2
        left_mid = sorted_q[ql] if ql < mid else sorted_q[mid]
        right_mid = sorted_q[qr] if qr < mid else sorted_q[mid]

        best = tree[node]
        if best is not None:
            best_val = get_value(best[0], best[1], sorted_q[mid])
            if get_value(a, b, sorted_q[ql] | sorted_q[q]) < best_val or a > best[0] or b > tree[node]:
                if ql == qr:
                    tree[node] = best
                elif left_mid < sorted_q[q]:
                    update(node * 2, ql, mid, a, b, v)
                else:
                    update(node * 2 + 1, mid + 1, qr, a, b, v)
        elif ql == qr:
            tree[node] = (a, b)

    def query(node, ql, qr, a, b, qidx, v):
        if ql == qr: return tree
        mid = (ql + qr) // 2
        if v < ql:
            res = get_value(a, b, sorted_q[qidx])
            if tree[node] is not None:
                res = max(res, get_value(tree[node][0], tree[node][1], [ql, qr]))
            update()
        return res

    res = []
    active = {}

    for q in range(1, n + 1):
        t, *data = queries[q]
        if t == 1:
            a, b = data
            active[(a, b)] += 1
            update(1, 0, m - 1, a, b, 0, a*q[2] + b)
        elif t == 2:
            a, b = data, len(active) - 1
