    usable = n - 2 * m
    if usable <= 0:
        return "0\n"

    # Equilateral triangle vertices
    v1 = (0.0, 0.0)
    v2 = (1.0, 0.0)
    v3 = (0.5, math.sqrt(3) / 2)

    def get_pos(side, fraction):
        """Get position on a triangle side given a normalized fraction [0,1]"""
        if side == 0:
            return (v1[0] + fraction * (v2[0] - v1[0]), v1[1] + fraction * (v2[1] - v1[1]))
        elif side == 1:
            return (v2[0] + fraction * (v3[0] - v2[0]), v2[1] + fraction * (v3[1] - v2[1]))
        else:
            return (v3[0] + fraction * (v1[0] - v3[0]), v3[1] + fraction * (v1[1] - v3[1]))

    def dist_sq(p1, p2):
        """Squared Euclidean distance between two points"""
        return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

    ans = 0

    # Enumerate all possible triangles (one hole from each side)
    # Hole positions are indexed from 0 to usable-1
    frac_step = 1 / usable

    for t1 in range(usable):
        p1 = get_pos(0, t1 * frac_step)
        for t2 in range(usable):
            p2 = get_pos(1, t2 * frac_step)
            for t3 in range(usable):
                p3 = get_pos(2, t3 * frac_step)

